contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _target, uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value, "test must hold value");
        require(_target != address(c), "target must not be c");

        uint balCBefore = address(c).balance;
        uint balTBefore = _target.balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.sendMoney(_target, _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted
                ? (address(c).balance == balCBefore &&
                   _target.balance == balTBefore &&
                   c.depositsCount() == depositsBefore)
                : (address(c).balance == balCBefore - _value &&
                   _target.balance == balTBefore + _value &&
                   c.depositsCount() == depositsBefore)
        );
    }

    receive() external payable {}
}

