pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address _target, uint256 _value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _value);
        vm.assume(_target != address(c));
        uint balCBefore = address(c).balance;
        uint balTBefore = _target.balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool reverted;
        try c.sendMoney(_target, _value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted
                ? (address(c).balance == balCBefore &&
                   _target.balance == balTBefore &&
                   c.depositsCount() == depositsBefore)
                : (address(c).balance == balCBefore - _value &&
                   _target.balance == balTBefore + _value &&
                   c.depositsCount() == depositsBefore));
    }

    function testFuzz_run(address _target, uint256 _value) public {
